const KEY='centrix-overview-demo-v1';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',file:'<path d="M14 2H5v20h14V7Z M14 2v6h5 M8 12h8 M8 16h6"/>',ship:'<path d="m3 15 9-4 9 4-3 5H6Z M6 13V7h12v6 M10 7V3h4v4 M2 22q3-3 6 0 4-3 8 0 3-3 6 0"/>',shield:'<path d="m12 2 9 4v6q0 7-9 10Q3 19 3 12V6Z m-5 10 3 3 7-7"/>',chart:'<path d="M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z M20 2v4 M18 4h4"/>',arrow:'<path d="M4 12h15 m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12 M6 18 18 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',board:'<rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="11" rx="1"/><rect x="17" y="4" width="4" height="14" rx="1"/>',list:'<path d="M8 6h13 M8 12h13 M8 18h13 M3 6h.1 M3 12h.1 M3 18h.1"/>',alert:'<path d="m12 3 10 18H2Z M12 9v5 M12 17v.2"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',back:'<path d="M20 12H4 m6-6-6 6 6 6"/>'};
function icon(n){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.file}</svg>`;}
document.querySelectorAll('[data-icon]').forEach(el=>el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)));
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
function dateLabel(d){if(!d)return 'Sem previsão';return new Date(d.slice(0,10)+'T12:00:00-03:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short',timeZone:'America/Sao_Paulo'}).replace('.','');}
const dayDiff=(a,b)=>Math.round((new Date(a+'T12:00:00-03:00')-new Date(b+'T12:00:00-03:00'))/86400000);
const age=p=>Math.max(0,dayDiff('2026-09-10',p.since));
const defaults={profile:'Mariana',mode:'board',owner:'all',flag:'all',stage:'all',search:'',myFilter:'all',scope:'mine',done:[],results:{},followups:{},watched:[],reviewed:[],updated:false,read:[]};
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}
// Old numeric stage filters referred to a different journey. Preserve other local work.
if(saved.journeyVersion!==2){saved.stage='all';saved.journeyVersion=2;}
let state={...defaults,...saved}, processes=structuredClone(INITIAL_PROCESSES), tab='dia', drawerProcess=null, returnFocus=null, pendingUpdate=false, toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function applyChanges(){processes=structuredClone(INITIAL_PROCESSES);for(const p of processes){if(state.done.includes(p.id)){p.action=null;p.blocked=false;p.status=({ 'PR-26028':'Booking aprovado; coleta prevista','PR-26012':'Documento complementado; em análise','PR-26034':'Proposta selecionada; aguardando reserva','PR-26036':'Orçamento aprovado; contratação liberada','PR-26005':'Caso revisado; envio pelo cliente pendente'})[p.id]||'Ação registrada';}if(state.followups[p.id]&&p.waiting)p.waiting.followup=state.followups[p.id];}if(state.updated){const p=processes.find(p=>p.id==='PR-26019A');p.date='2026-09-18';p.risk=true;p.status='Chegada ao porto reprogramada';p.updated='10/09 às 10h45';p.events.unshift({time:'Hoje, 10h45',title:'Nova previsão para o lote 1',text:'Chegada ao porto alterada de 16/09 para 18/09. Motivo ainda não informado pelo agente.',before:'16 set',after:'18 set',source:'Atualização demonstrativa do agente'});}}
function allTasks(){return processes.filter(p=>p.action&&!state.done.includes(p.id));}
function tasks(){return allTasks().filter(p=>state.scope==='shared'||p.action.owner===state.profile);}
function waits(){return processes.filter(p=>p.waiting&&(state.scope==='shared'||p.owner===state.profile));}
function due(p){if(!p.action?.deadline)return 'later';const d=new Date(p.action.deadline);return d<NOW?'overdue':p.action.deadline.startsWith('2026-09-10')?'today':'later';}
function dueLabel(p){if(!p.action?.deadline)return 'Sem prazo definido';let t=new Date(p.action.deadline).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'});return due(p)==='overdue'?`Venceu hoje às ${t}`:`Hoje, até ${t}`;}
function initials(name){return name==='Mariana'?'ML':name==='Rafael'?'RC':'BA';}
function avatar(name){return `<span class="avatar tiny ${name==='Rafael'?'rafael':''}">${initials(name)}</span>`;}
function person(name){return name===state.profile?'Você':name;}
function pill(p){return p.blocked?'<span class="pill danger">Bloqueado</span>':p.risk?'<span class="pill warning">Chegada alterada</span>':p.stale?'<span class="pill info">Sem atualização</span>':'<span class="pill success">Em andamento</span>';}
function empty(title,desc){return `<div class="empty">${icon('check')}<h3>${title}</h3><p>${desc}</p></div>`;}
function render(){applyChanges();tab=['dia','operacao'].includes(location.hash.slice(1))?location.hash.slice(1):'dia';$('.profile select').value=state.profile;$('#avatar').textContent=initials(state.profile);$('#avatar').classList.toggle('rafael',state.profile==='Rafael');document.querySelectorAll('[data-tab]').forEach(el=>{const active=el.dataset.tab===tab;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#my-count').textContent=allTasks().filter(p=>p.action.owner===state.profile).length||'';$('#subtitle').textContent=({dia:'Suas prioridades, o contexto e o próximo passo.',operacao:'Cotações e embarques, com o acompanhamento disponível.'})[tab];$('#content').innerHTML=tab==='dia'?renderDay():renderOperation();$('#snapshot-time').textContent=`Base do cenário · ${state.updated?'10h45':'10h30'}`;$('#simulate').disabled=state.updated||pendingUpdate;$('#simulate').textContent=state.updated?'Atualização aplicada':'Simular atualização';save();}
function renderDay(){let ts=tasks(),ws=waits();const late=ts.filter(p=>due(p)==='overdue'),today=ts.filter(p=>due(p)==='today');const countText=state.scope==='shared'?'Pendências da empresa':'Ações atribuídas a você';let shown=ts.filter(p=>state.myFilter==='all'||state.myFilter===due(p)).sort((a,b)=>(due(a)==='overdue'?0:due(a)==='today'?1:2)-(due(b)==='overdue'?0:due(b)==='today'?1:2)||(new Date(a.action.deadline||'2099-01-01')-new Date(b.action.deadline||'2099-01-01')));const metric=(key,n,label,note,cls='')=>`<button class="metric ${state.myFilter===key?'selected':''}" data-cmd="myfilter" data-value="${key}" aria-pressed="${state.myFilter===key}"><span class="metric-num ${cls}">${n}</span><span><span class="metric-label">${label}</span><span class="metric-note">${note}</span></span>${icon('arrow')}</button>`;
const events=processes.filter(p=>p.events.length&&(state.profile==='Rafael'||p.owner===state.profile||state.watched.includes(p.id))).flatMap(p=>p.events.map((e,i)=>({p,e,i}))).sort((a,b)=>b.e.time.localeCompare(a.e.time));
return `<div class="metrics">${metric('overdue',late.length,'Ações vencidas','Precisam de uma decisão','red')}${metric('today',today.length,'Ações para hoje','Ainda dentro do prazo','amber')}${metric('waiting',ws.length,'Aguardando retorno','Você acompanha; outra pessoa age')}</div><div class="day-grid"><div><section class="surface"><div class="section-head"><div class="section-title"><h2>Fazer agora</h2><span class="count">${shown.length}</span></div>${state.myFilter!=='all'?'<button class="link-button" data-cmd="myfilter" data-value="all">Limpar recorte</button>':`<span class="small muted">${countText}</span>`}</div><div class="scope-tabs" aria-label="Escopo de ações"><button data-cmd="scope" data-value="mine" class="${state.scope==='mine'?'active':''}" aria-pressed="${state.scope==='mine'}">Minhas ações</button><button data-cmd="scope" data-value="shared" class="${state.scope==='shared'?'active':''}" aria-pressed="${state.scope==='shared'}">Fila compartilhada</button></div>${state.myFilter==='waiting'?empty('Você está acompanhando retornos','A fila abaixo mostra quem precisa agir e o próximo acompanhamento.'):shown.length?shown.map(p=>`<div class="task-row ${due(p)==='overdue'?'urgent':due(p)==='today'?'today':''}"><span class="task-marker"></span><div><div class="task-title">${p.action.title}</div><p class="task-meta">${p.name} · ${p.po} · ${p.id}</p><div class="task-bottom"><span class="pill ${due(p)==='overdue'?'danger':due(p)==='today'?'warning':''}">${dueLabel(p)}</span>${state.scope==='shared'?`<span>${person(p.action.owner)}</span>`:''}<span>${p.action?.type==='audit'?'Conferência':'Próxima ação do processo'}</span></div></div><button class="button" data-cmd="detail" data-id="${p.id}">${p.action.cta}</button></div>`).join(''):empty('Nenhuma ação neste recorte','Consulte os retornos que você acompanha ou abra a fila completa.')}</section><section class="surface waiting" id="waiting-list"><div class="section-head"><div class="section-title"><h2>Aguardando retorno</h2><span class="count">${ws.length}</span></div><span class="small muted">Responsabilidade clara</span></div>${ws.length?ws.map(p=>`<div class="wait-row"><div><p><strong>${p.name}</strong> · ${p.po}</p><small>Depende de <strong>${p.waiting.executor}</strong></small><div class="task-bottom" style="margin-top:7px">${icon('clock')}<span>Acompanhar ${dateLabel(p.waiting.followup)}, ${p.waiting.followup.slice(11)} · ${person(p.owner)}</span></div></div><button class="link-button" data-cmd="detail" data-id="${p.id}">Ver pendência ${icon('chevron')}</button></div>`).join(''):empty('Nenhum retorno pendente','Os acompanhamentos com terceiros aparecerão aqui.')}</section></div><div><section class="surface"><div class="section-head"><h2>O que mudou</h2><span class="small muted">Hoje</span></div><p class="section-desc">${state.profile==='Rafael'?'Mudanças relevantes da equipe.':'Nos processos sob seus cuidados.'}</p><div class="activity">${events.length?events.map(({p,e,i})=>`<article class="event"><div class="event-time"><span>${e.time}</span><button class="icon-button" style="min-height:20px;min-width:20px" data-cmd="read" data-value="${p.id}-${i}" aria-label="${state.read.includes(p.id+'-'+i)?'Marcar como não lido':'Marcar como lido'}">${state.read.includes(p.id+'-'+i)?icon('check'):'<span class="status-dot"></span>'}</button></div><button class="event-title" data-cmd="detail" data-id="${p.id}">${e.title}</button><p>${p.name} · ${p.po}</p>${e.before?`<div class="delta"><span>${e.before}</span>${icon('arrow')}<strong>${e.after}</strong></div>`:`<p>${e.text}</p>`}<button class="link-button" data-cmd="detail" data-id="${p.id}">Entender mudança ${icon('chevron')}</button></article>`).join(''):empty('Nenhuma mudança recente','Acompanhe um processo na Operação para incluir suas atualizações.')}</div><div class="watch-note">Ler um aviso não encerra a pendência. A conclusão vem da ação no processo.</div></section><div class="tip-card"><strong>A operação continua além da sua fila.</strong><p>Veja também o que está andando normalmente e o que depende de outras pessoas.</p><button class="link-button" data-cmd="goop">Abrir toda a operação ${icon('arrow')}</button></div></div></div>`;}
function filteredProcesses(){return processes.filter(p=>(state.owner==='all'||p.owner===state.owner)&&(state.stage==='all'||p.stage===Number(state.stage))&&(state.flag==='all'||state.flag==='blocked'&&p.blocked||state.flag==='risk'&&p.risk||state.flag==='stale'&&p.stale||state.flag==='ready'&&!!p.ready||state.flag==='audit'&&!!p.audit)&&(p.name+' '+p.po+' '+p.id+' '+p.supplier).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(state.search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));}
function renderOperation(){let ps=filteredProcesses();const hasFilter=state.owner!=='all'||state.stage!=='all'||state.flag!=='all'||state.search;const common=processes.filter(p=>(state.owner==='all'||p.owner===state.owner)&&(state.stage==='all'||p.stage===Number(state.stage))&&(p.name+' '+p.po+' '+p.id+' '+p.supplier).toLowerCase().includes(state.search.toLowerCase()));const chip=(flag,name,n,cls)=>`<button class="filter-chip ${state.flag===flag?'active':''}" data-cmd="flag" data-value="${flag}" aria-pressed="${state.flag===flag}"><span class="${cls}">●</span>${name}<strong>${n}</strong></button>`;
return `<div class="coverage"><strong>Cobertura desta carteira:</strong> cotações, contratação e tracking internacional. Prontidão e coleta aparecem apenas como informação complementar. Liberação e entrega na fábrica não estão acompanhadas.</div><div class="op-summary"><span class="op-total"><b>${ps.length}</b> operações acompanhadas</span>${chip('blocked','Bloqueadas',common.filter(p=>p.blocked).length,'red')}${chip('risk','Chegada alterada',common.filter(p=>p.risk).length,'amber')}${chip('stale','Sem atualização',common.filter(p=>p.stale).length,'muted')}<div class="mode-switch" aria-label="Visualização"><button data-cmd="mode" data-value="board" class="${state.mode==='board'?'active':''}" aria-pressed="${state.mode==='board'}">${icon('board')}Por etapa</button><button data-cmd="mode" data-value="list" class="${state.mode==='list'?'active':''}" aria-pressed="${state.mode==='list'}">${icon('list')}Lista</button></div></div><div class="toolbar"><label class="searchbox">${icon('search')}<input id="search" type="search" aria-label="Buscar processo, PO, item ou fornecedor" placeholder="Buscar processo, PO, item..." value="${esc(state.search)}"></label><select class="select-filter" id="owner" aria-label="Responsável pelo acompanhamento"><option value="all">Todos os responsáveis</option>${['Mariana','Beatriz','Rafael'].map(n=>`<option value="${n}" ${state.owner===n?'selected':''}>${n}</option>`).join('')}</select><select class="select-filter" id="stage" aria-label="Etapa"><option value="all">Todas as etapas</option>${STAGES.map((s,i)=>`<option value="${i}" ${state.stage===String(i)?'selected':''}>${s}</option>`).join('')}</select>${hasFilter?'<button class="link-button" data-cmd="clearop">Limpar filtros</button>':''}<span class="toolbar-end">${state.flag==='ready'?'Recorte: prontidão com coleta sem confirmação · ':state.flag==='audit'?'Recorte: divergência fundamentada · ':''}${new Set(processes.map(p=>p.po)).size} POs · ${processes.length} operações na carteira</span></div>${ps.length?(state.mode==='board'?board(ps):processTable(ps)):`<section class="surface">${empty('Nenhum processo encontrado','Ajuste a busca ou limpe os filtros para voltar à carteira completa.')}<div style="text-align:center;padding-bottom:20px"><button class="button" data-cmd="clearop">Limpar filtros</button></div></section>`}<p class="board-foot">${icon('clock')} ${state.mode==='board'?'Cada coluna mostra todas as operações do recorte. Tempo na etapa em dias corridos.':'Os dois lotes do PO 1782 são operações distintas, vinculadas ao mesmo pedido.'} Processos sem exceção também estão incluídos.</p><p class="board-foot">Cenário demonstrativo: “sem atualização” usa mais de 3 dias sem registro da fonte; chegada alterada compara a previsão atual com a primeira. Conferências e documentos são situações paralelas, não etapas da viagem. Os dados e fontes desta prévia são fictícios.</p>`;}
function board(ps){return `<div class="board-wrap" tabindex="0" aria-label="Fila completa por etapa, role horizontalmente em telas pequenas"><div class="board">${STAGES.map((s,i)=>{const list=ps.filter(p=>p.stage===i).sort((a,b)=>Number(b.blocked)-Number(a.blocked)||Number(b.risk)-Number(a.risk));return `<section class="stage"><div class="stage-head"><div class="stage-title"><span>${s}</span><span class="stage-n">${list.length}</span></div><p class="stage-note">${STAGE_NOTES[i]}</p><div class="stage-meta">${list.filter(p=>p.blocked).length?`<span class="red">${list.filter(p=>p.blocked).length} bloqueada(s)</span> · `:''}${list.length?`Mais antiga: ${Math.max(...list.map(age))}d`:'Nenhum processo neste recorte'}</div></div>${list.map(p=>`<button class="process-card ${p.blocked?'blocked':p.risk?'risk':''}" data-cmd="detail" data-id="${p.id}" aria-label="Abrir ${p.name}, ${p.id}"><span class="card-ref">${p.id}${state.watched.includes(p.id)?icon('star'):''}</span><div class="card-title">${p.name}</div><div class="card-po">${p.po}${p.split?' · parcial':''}</div>${p.blocked||p.risk||p.stale?pill(p):''}<div class="card-status">${p.status}</div><div class="card-source">${p.coverage}</div><div class="card-milestone"><span>${p.milestone}</span><strong>${dateLabel(p.date)}</strong></div><div class="card-owner">${avatar(p.owner)}${p.owner}<span style="margin-left:auto">${age(p)}d na etapa</span></div></button>`).join('')}</section>`;}).join('')}</div></div>`;}
function processTable(ps){return `<div class="surface"><div class="table-wrap"><table class="process-table"><thead><tr><th>Processo / carga</th><th>Etapa e situação</th><th>Próxima ação / responsável</th><th>Marco acompanhado</th></tr></thead><tbody>${ps.map(p=>`<tr><td><button class="row-link" data-cmd="detail" data-id="${p.id}">${p.name}</button><small>${p.id} · ${p.po}</small>${p.split?'<small>Pedido dividido em 2 lotes</small>':''}</td><td>${STAGES[p.stage]}<small>${p.status}</small>${p.blocked||p.risk||p.stale?`<div style="margin-top:6px">${pill(p)}</div>`:''}</td><td>${p.action?.title||p.waiting?.title||'Acompanhar próximo marco'}<small>${p.waiting?`Depende de ${p.waiting.executor} · `:''}${p.owner} acompanha</small></td><td><strong>${dateLabel(p.date)}</strong><small>${p.milestone}</small><small>${p.updated}</small></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${ps.length} operações neste recorte</span><span>Cotação e embarque vinculados no mesmo processo</span></div></div>`;}
function showDrawer(title,sub,body,back=''){if(!$('#drawer').hidden){}else{returnFocus=document.activeElement;}$('#drawer').innerHTML=`<div class="drawer-head"><div>${back?`<button class="link-button" data-cmd="${back}" ${drawerProcess?`data-id="${drawerProcess}"`:''}>${icon('back')}Voltar</button>`:''}<div class="small">${sub}</div><h2 id="drawer-title">${title}</h2></div><button class="icon-button" data-cmd="close" aria-label="Fechar painel">${icon('close')}</button></div><div class="drawer-body">${body}</div>`;$('#drawer').hidden=false;$('#backdrop').hidden=false;document.body.classList.add('drawer-open');$('#drawer').scrollTop=0;$('#drawer button')?.focus();}
function closeDrawer(){if($('#drawer').hidden){drawerProcess=null;return;}let el=returnFocus;$('#drawer').hidden=true;$('#backdrop').hidden=true;document.body.classList.remove('drawer-open');drawerProcess=null;if(el?.isConnected)el.focus({preventScroll:true});else $('#main').focus({preventScroll:true});}
function detail(id){const p=processes.find(p=>p.id===id);if(!p)return;drawerProcess=id;let actionBlock=p.action?`<div class="detail-action"><span class="pill ${due(p)==='overdue'?'danger':'warning'}">${dueLabel(p)}</span><h3>${p.action.title}</h3><p>${p.action.reason} ${p.action.effect}</p><div class="small">Responsável pela ação: <strong>${person(p.action.owner)}</strong></div>${p.action.owner===state.profile?`<button class="button primary" data-cmd="action" data-id="${p.id}">${p.action.cta}</button>`:`<p class="small">A decisão está atribuída a ${p.action.owner}. Troque o perfil na prévia para experimentar esse trabalho.</p>`}</div>`:p.waiting?`<div class="detail-action"><span class="pill">Aguardando retorno</span><h3>${p.waiting.title}</h3><p>${p.waiting.effect}</p><div class="small">Depende de <strong>${p.waiting.executor}</strong></div><div class="small">Próximo acompanhamento: <strong>${dateLabel(p.waiting.followup)} às ${p.waiting.followup.slice(11)}</strong></div><button class="button" data-cmd="followup" data-id="${p.id}">Programar acompanhamento</button></div>`:`<div class="detail-action"><span class="pill success">${state.done.includes(p.id)?'Ação registrada na prévia':'Acompanhamento'}</span><h3>${p.status}</h3><p>${p.risk?'A mudança precisa ser considerada no planejamento. A causa deve ser confirmada com a fonte.':'O próximo marco continua visível na operação. Nenhuma ação adicional foi atribuída a você.'}</p>${state.done.includes(p.id)?'<p class="small">Resultado simulado neste navegador. Nenhuma alteração foi enviada ao Centrix.</p>':''}</div>`;
showDrawer(p.name,`${p.id} · ${p.po}`,`<div class="detail-intro">${pill(p)}<button class="button small-btn" data-cmd="watch" data-id="${p.id}" aria-pressed="${state.watched.includes(p.id)}">${icon('star')}${state.watched.includes(p.id)?'Acompanhando':'Acompanhar'}</button></div>${actionBlock}<dl class="detail-dl"><div><dt>Etapa atual</dt><dd>${STAGES[p.stage]} · ${age(p)} dias</dd></div><div><dt>Responsável por acompanhar</dt><dd>${p.owner} ${p.owner===state.profile?'(você)':''}</dd></div><div><dt>Fornecedor</dt><dd>${p.supplier}</dd></div><div><dt>Rota / modal</dt><dd>${p.route}<br>${p.modal}</dd></div></dl>${p.split?`<div class="notice">${p.split}. Cada lote mantém seu embarque, prazo e situação. O pedido não foi duplicado.</div>`:''}<section class="detail-section"><h3>Marco acompanhado e cobertura</h3><div class="notice">${p.coverageNote}</div><div class="timeline"><div class="timeline-item complete"><strong>Entrada em ${STAGES[p.stage].toLowerCase()}</strong><p>${dateLabel(p.since)} · Registro do cenário</p></div><div class="timeline-item"><strong>${p.milestone}</strong><p>${p.date?`${dateLabel(p.date)} · ${p.actual?'Realizado':'Previsto'}`:'Previsão ainda não informada'}</p>${p.date&&p.baseline&&p.date!==p.baseline?`<p>Primeira previsão: ${dateLabel(p.baseline)} · alteração de ${dayDiff(p.date,p.baseline)} dias</p>`:''}</div></div>${p.milestone==='Chegada ao porto'?'<div class="notice">Esta data é de chegada ao porto. Disponibilidade na fábrica ainda não informada.</div>':''}${p.stale?'<div class="notice">Sem atualização desde 05/09. Ausência de retorno não confirma atraso operacional.</div>':''}</section><section class="detail-section"><h3>Histórico e fontes</h3>${state.done.includes(p.id)?`<div class="timeline-item complete"><strong>Ação registrada nesta prévia</strong><p>${esc(state.results[p.id]||'Resultado local disponível na fila.')} Nenhum envio externo.</p></div>`:''}${p.events.length?p.events.map(e=>`<div class="timeline-item"><small>${e.time}</small><strong>${e.title}</strong><p>${e.text}</p><small>Fonte: ${e.source}</small></div>`).join(''):'<p class="small muted">Não há outras alterações registradas neste cenário.</p>'}<div class="source-note">${p.source} · ${p.updated}<br>Documento e eventos fictícios para avaliação da experiência.</div></section><section class="detail-section"><h3>Continuidade do processo</h3><p class="small muted">${p.quote||p.shipment||'Identificação de embarque ainda não disponível.'}</p>${p.audit?`<div class="delta"><span>Diferença fundamentada</span><strong>${money(p.audit.questionable)}</strong></div><button class="link-button" data-cmd="action" data-id="${p.id}">Reabrir caso de cobrança</button>`:''}<div class="form-actions"><button class="button" data-cmd="ask">${icon('spark')}Consultar este processo</button><button class="button" data-cmd="viewstage" data-value="${p.stage}">Ver etapa</button></div></section>`);}
function action(id){const p=processes.find(p=>p.id===id);if(!p||(!p.action&&!p.audit))return;const type=p.action?.type||'audit';let body='';
if(type==='quote')body=`<h3>Escolha considerando custo e chegada</h3><p class="small muted" style="margin-top:7px">${p.route} · Chegada ao aeroporto · Valores fictícios</p><table class="detail-mini-table"><thead><tr><th>Agente</th><th>Total BRL</th><th>Chegada</th></tr></thead><tbody><tr><td>Atlas Cargo</td><td>R$ 8.810</td><td>19 set</td></tr><tr><td>Meridian</td><td>R$ 9.370</td><td>17 set</td></tr><tr><td>Ponte Log</td><td>R$ 9.540</td><td>18 set</td></tr></tbody></table><label class="form-field">Proposta escolhida<select id="proposal"><option>Atlas Cargo · R$ 8.810 · 19 set</option><option>Meridian · R$ 9.370 · 17 set</option><option>Ponte Log · R$ 9.540 · 18 set</option></select></label>`;
if(type==='booking')body=`<h3>Conferir antes do aceite</h3><dl class="detail-dl"><div><dt>Booking</dt><dd>BK-DEMO-028</dd></div><div><dt>Coleta</dt><dd>12 set · Shanghai</dd></div><div><dt>Equipamento</dt><dd>1 × 40 HC</dd></div><div><dt>Partida prevista</dt><dd>15 set 2026</dd></div><div><dt>Chegada ao porto</dt><dd>14 out · Santos</dd></div><div><dt>Condição</dt><dd>FOB · Proposta aceita</dd></div></dl><p class="small muted">A aprovação confirma os dados do booking. Não confirma o embarque realizado.</p>`;
if(type==='document')body=`<h3>Falta informar o Incoterm</h3><p class="muted" style="margin:12px 0">A invoice recebida não permite concluir a conferência documental. O cenário inclui uma versão corrigida para experimentar o complemento.</p><div class="source-note">Invoice-DEMO-012-revisada.pdf<br>Incoterm FOB · Dados fictícios · Versão de demonstração</div><label class="form-field">Documento do cenário<select><option>Usar invoice corrigida do exemplo</option></select></label><p class="small muted">O complemento encaminha o documento para análise; não representa aprovação.</p>`;
if(type==='budget')body=`<h3>Decisão dentro da sua alçada</h3><table class="detail-mini-table"><tr><td>Orçamento aprovado</td><td>R$ 18.000</td></tr><tr><td>Condição disponível</td><td>R$ 19.200</td></tr><tr><td>Diferença</td><td>R$ 1.200 · 6,7%</td></tr></table><p class="small muted">Motivo registrado: alternativa atende à janela solicitada. A decisão é atribuída ao gestor neste cenário.</p>`;
if(type==='audit')body=`<h3>Fundamentação da divergência</h3><table class="detail-mini-table"><tr><th>Item cobrado</th><th>Diferença</th></tr><tr><td>Taxa documental não prevista</td><td>R$ 120</td></tr><tr><td>Taxa adicional sem respaldo</td><td>R$ 450</td></tr><tr><td><strong>Total para questionar</strong></td><td><strong>R$ 570</strong></td></tr></table><div class="source-note">Fontes demonstrativas: proposta aceita COT-DEMO-005 e fatura FAT-DEMO-005.</div><p style="margin-top:15px;font-size:13px">O caso está pronto para sua avaliação. Você conduz o envio e a negociação; exportar não significa enviar ou recuperar o valor.</p><button class="button" data-cmd="download" data-id="${id}" style="margin-top:14px">Baixar resumo demonstrativo</button>`;
drawerProcess=id;showDrawer(p.action?.title||'Caso de cobrança',`${p.id} · ${p.po}`,`${body}<div class="notice">Simulação local. Esta ação só altera os dados fictícios desta prévia.</div><div class="form-actions"><button class="button primary" data-cmd="resolve" data-id="${id}" ${!p.action?'disabled':''}>${({quote:'Confirmar escolha na prévia',booking:'Aprovar booking na prévia',document:'Adicionar complemento na prévia',budget:'Aprovar orçamento na prévia',audit:'Marcar caso como revisado'})[type]}</button><button class="button" data-cmd="detail" data-id="${id}">Voltar</button></div>`,'detail');}
function followup(id){const p=processes.find(p=>p.id===id);drawerProcess=id;showDrawer('Programar acompanhamento',`${p.id} · ${p.waiting.executor}`,`<p class="muted">A pendência continua com ${p.waiting.executor}. Você define quando voltar a acompanhar.</p><label class="form-field">Próximo acompanhamento<input id="followup-date" type="datetime-local" min="2026-09-10T10:30" value="${p.waiting.followup}" required></label><p class="small muted">Horário de São Paulo. Simulação local; nenhum lembrete externo será enviado.</p><p id="form-error" class="red small" role="alert"></p><div class="form-actions"><button class="button primary" data-cmd="savefollowup" data-id="${id}">Salvar acompanhamento</button><button class="button" data-cmd="detail" data-id="${id}">Cancelar</button></div>`,'detail');}
function ask(query){const ctx=drawerProcess;showDrawer('Perguntar ao Centrix',ctx?`Contexto: ${ctx}`:'Consulta da carteira',`<p class="muted" style="font-size:13px;margin-bottom:15px">Um caminho curto até a informação e os processos que explicam a resposta.</p><label class="form-field">Escopo da consulta<select id="query-scope"><option value="context">${ctx?'Este processo':tab==='operacao'?'Recorte atual da Operação':'Carteira sob minha responsabilidade'}</option><option value="all">Toda a carteira da empresa</option></select></label><div class="coverage">Consultas predefinidas calculadas sobre os dados fictícios. Linguagem livre é uma evolução futura.</div>${[['mine','O que depende de mim hoje?'],['ready','Quais cargas estão prontas e sem coleta?'],['changes','O que mudou na chegada?'],['audit','Quais cobranças têm divergência?']].map(([key,label])=>`<button class="question" data-cmd="question" data-value="${key}">${label}${icon('arrow')}</button>`).join('')}<div id="answer" aria-live="polite"></div>`,ctx?'detail':'');if(query)answer(query);}
function queryBase(){if($('#query-scope')?.value==='all')return processes;if(drawerProcess)return processes.filter(p=>p.id===drawerProcess);return tab==='operacao'?filteredProcesses():processes.filter(p=>p.owner===state.profile);}
function answer(q){const base=queryBase();let list=[],description='',title='';if(q==='mine'){list=base.filter(p=>p.action&&p.action.owner===state.profile);title=`${list.length} ${list.length===1?'ação atribuída':'ações atribuídas'} a você`;description='Pendências abertas no escopo escolhido. Ações sem prazo também permanecem visíveis.';}if(q==='ready'){list=base.filter(p=>p.ready&&p.stage===1);title=`${list.length} carga${list.length===1?'':'s'} pronta${list.length===1?'':'s'} com coleta sem confirmação`;description='Informação complementar de prontidão registrada no exemplo; coleta sem confirmação. Ausência de registro não comprova que a coleta não ocorreu. A fonte precisa estar integrada para oferecer esta consulta.';}if(q==='changes'){list=base.filter(p=>p.risk&&p.events.length);title=`${list.length} chegada${list.length===1?'':'s'} alterada${list.length===1?'':'s'}`;description='Previsões de chegada ao porto comparadas com a primeira previsão. A causa só aparece quando registrada pela fonte.';}if(q==='audit'){list=base.filter(p=>p.audit?.questionable>0);title=`${money(list.reduce((s,p)=>s+p.audit.questionable,0))} para questionar`;description='Conferências fundamentadas dos processos ativos deste escopo. Não representa economia ou valor recuperado.';}$('#answer').innerHTML=`<div class="answer"><h3>${title}</h3><p>${description}</p>${list.map(p=>`<button class="answer-result" data-cmd="detail" data-id="${p.id}"><strong>${p.name}</strong><small>${p.po} · ${p.status}</small><small>Fonte: ${p.source} · ${p.updated}</small></button>`).join('')||'<p style="margin-top:10px">Nenhum registro com os dados necessários neste recorte. Isso não comprova ausência de risco fora da cobertura da prévia.</p>'}<div class="source-note">Base do cenário: ${state.updated?'10h45':'10h30'} · 10/09/2026<br>Escopo: ${$('#query-scope').selectedOptions[0].textContent}</div></div>`;$('#answer').scrollIntoView({block:'nearest',behavior:'smooth'});}
function notify(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4300);}
function goOperation(opts={}){Object.assign(state,{owner:'all',flag:'all',stage:'all',search:''},opts);closeDrawer();if(location.hash!=='#operacao')location.hash='operacao';else render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-cmd]');if(!b)return;const c=b.dataset.cmd,id=b.dataset.id,v=b.dataset.value;
switch(c){case 'myfilter':state.myFilter=state.myFilter===v?'all':v;render();break;case 'scope':state.scope=v;render();break;case 'detail':detail(id);break;case 'close':closeDrawer();break;case 'mode':state.mode=v;render();break;case 'flag':state.flag=state.flag===v?'all':v;render();break;case 'clearop':Object.assign(state,{owner:'all',flag:'all',stage:'all',search:''});render();break;case 'goop':goOperation();break;case 'viewstage':goOperation({stage:v});break;case 'watch':state.watched=state.watched.includes(id)?state.watched.filter(x=>x!==id):[...state.watched,id];save();detail(id);break;case 'read':state.read=state.read.includes(v)?state.read.filter(x=>x!==v):[...state.read,v];render();break;case 'ask':ask();break;case 'question':answer(v);break;case 'action':action(id);break;case 'followup':followup(id);break;case 'savefollowup':{const input=$('#followup-date');if(!input.checkValidity()||!input.value){$('#form-error').textContent='Escolha um horário a partir de 10/09 às 10h30, o momento deste cenário.';input.reportValidity();break;}state.followups[id]=input.value;save();render();detail(id);notify('Próximo acompanhamento salvo nesta prévia.');break;}case 'resolve':{const p=processes.find(p=>p.id===id);if(!p?.action||p.action.owner!==state.profile)break;state.results[id]=p.action.type==='quote'?('Proposta escolhida: '+document.querySelector('#proposal').value):p.action.type==='booking'?'Booking BK-DEMO-028 aprovado; coleta prevista para 12/09.':p.action.type==='document'?'Invoice revisada adicionada; documento permanece em análise.':p.action.type==='budget'?'Exceção de orçamento de R$ 1.200 aprovada.':'Caso revisado; envio ao destinatário permanece sob responsabilidade do cliente.';state.done=[...new Set([...state.done,id])];save();render();detail(id);notify('Ação registrada na prévia. A fila foi atualizada.');break;}case 'download':{const p=processes.find(p=>p.id===id);const txt=`CENTRIX — RESUMO DEMONSTRATIVO\n${p.id} — ${p.name}\n${p.po}\nDados fictícios. Não enviar como contestação real.\n\nTaxa documental: R$ 120\nTaxa adicional: R$ 450\nTotal fundamentado do exemplo: R$ 570\n\nFontes demonstrativas: COT-DEMO-005 / FAT-DEMO-005.\nNenhum envio ou recuperação realizado.`;const url=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Centrix-caso-DEMO-005.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Resumo demonstrativo baixado. Nenhum envio realizado.');break;}case 'applyupdate':state.updated=true;pendingUpdate=false;$('#update-banner').hidden=true;save();render();notify('Nova previsão aplicada. A fila e os indicadores usam a mesma atualização.');break;case 'confirmreset':localStorage.removeItem(KEY);state=structuredClone(defaults);pendingUpdate=false;$('#update-banner').hidden=true;closeDrawer();location.hash='dia';render();notify('Cenário inicial restaurado.');break;
}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='profile'){state.profile=el.value;state.scope='mine';state.myFilter='all';closeDrawer();location.hash=el.value==='Rafael'?'operacao':'dia';render();}if(el.id==='owner'){state.owner=el.value;render();}if(el.id==='stage'){state.stage=el.value;render();}if(el.id==='query-scope')$('#answer').innerHTML='';});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;state.search=e.target.value;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#drawer').hidden)closeDrawer();if(e.key==='Tab'&&!$('#drawer').hidden){const focusable=[...$('#drawer').querySelectorAll('button,a[href],input,select,[tabindex="0"]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
$('#backdrop').addEventListener('click',closeDrawer);$('#simulate').addEventListener('click',()=>{if(state.updated)return;pendingUpdate=true;$('#simulate').disabled=true;$('#update-banner').hidden=false;$('#update-banner').innerHTML=`<span><strong>Uma nova informação chegou.</strong> O agente revisou a chegada do lote 1 do PO 1782.</span><button class="button small-btn" data-cmd="applyupdate">Aplicar atualização</button>`;notify('A atualização aguarda sua leitura. A lista não mudou de posição.');});
$('#reset').addEventListener('click',()=>{drawerProcess=null;showDrawer('Reiniciar demonstração','Dados locais desta prévia','<div class="reset-confirm"><p>Restaurar ações, acompanhamentos, filtros e atualizações do cenário inicial?</p><button class="button primary" data-cmd="confirmreset">Restaurar cenário</button> <button class="button" data-cmd="close">Cancelar</button></div>');});
window.addEventListener('hashchange',()=>{closeDrawer();render();});
render();
